function formatWhen(raw?: string | null) {
  if (!raw) return "-";
  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) return String(raw);
  return `${date.toLocaleDateString()} ${date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}`;
}

function isWithinRecentHours(raw: unknown, hours: number) {
  if (!raw) return false;
  const stamp = Date.parse(String(raw));
  if (!Number.isFinite(stamp)) return false;
  return Date.now() - stamp >= 0 && Date.now() - stamp <= hours * 60 * 60 * 1000;
}

function paymentReferralBonusStatus(statusRaw: unknown): "pending" | "given" | "not given" {
  const status = String(statusRaw || "").trim().toLowerCase();
  if (status === "given") return "given";
  if (status === "pending_accountless") return "pending";
  if (status === "pending_first_payment") return "not given";
  return "not given";
}

function labelFor(section: string, locale: Locale = "uz") {
  return sectionLabelByLocale(section, locale, SECTION_LABELS[section] || section);
}

function supportWeekdayName(weekday: number) {
  return SUPPORT_WEEKDAY_OPTIONS.find((item) => item.value === Number(weekday))?.label || String(weekday);
}

function prevMonth(ym: string) {
  const match = ym.match(/^(\d{4})-(\d{2})$/);
  if (!match) return null;
  let year = Number(match[1]);
  let month = Number(match[2]);
  if (month <= 1) {
    year -= 1;
    month = 12;
  } else {
    month -= 1;
  }
  return `${year}-${String(month).padStart(2, "0")}`;
}

function nextMonth(ym: string) {
  const match = ym.match(/^(\d{4})-(\d{2})$/);
  if (!match) return null;
  let year = Number(match[1]);
  let month = Number(match[2]);
  if (month >= 12) {
    year += 1;
    month = 1;
  } else {
    month += 1;
  }
  return `${year}-${String(month).padStart(2, "0")}`;
}

function lessonWindowFromParts(dateIso?: string, startRaw?: string, endRaw?: string) {
  const date = String(dateIso || "").trim();
  const startTime = String(startRaw || "00:00").slice(0, 5) || "00:00";
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return null;
  const startAt = new Date(`${date}T${startTime}:00`);
  if (Number.isNaN(startAt.getTime())) return null;
  const rawEnd = String(endRaw || "").slice(0, 5);
  const endTime = rawEnd || addMinutesToTime(startTime, 90);
  let endAt = new Date(`${date}T${endTime}:00`);
  if (Number.isNaN(endAt.getTime())) {
    endAt = new Date(startAt.getTime() + 90 * 60 * 1000);
  } else if (endAt <= startAt) {
    endAt = rawEnd ? new Date(endAt.getTime() + 24 * 60 * 60 * 1000) : new Date(startAt.getTime() + 90 * 60 * 1000);
  }
  return {
    startAt,
    endAt,
    openAt: new Date(startAt.getTime() - 10 * 60 * 1000),
    closeAt: new Date(endAt.getTime() + 24 * 60 * 60 * 1000),
  };
}

function buildUpcomingLessonCards(groups: GenericRow[], take = 40) {
  const now = new Date();
  const cards: Array<{
    group_id: number;
    group_name: string;
    date: string;
    start: string;
    end: string;
    label: string;
    is_open: boolean;
    is_closed: boolean;
    subject?: string;
    teacher_name?: string;
    student_count?: number;
  }> = [];
  const rankCard = (card: (typeof cards)[number]) => {
    if (card.is_open) return 0;
    if (!card.is_closed) return 1;
    return 2;
  };
  for (const group of groups) {
    const groupId = Number(group.id || 0);
    if (!groupId) continue;
    const groupCards: typeof cards = [];
    const lessonDateRaw = String(group.lesson_date || "").trim();
    const lessonStart = String(group.lesson_start || "18:00").slice(0, 5) || "18:00";
    const lessonEnd = String(group.lesson_end || "").slice(0, 5) || addMinutesToTime(lessonStart, 90);
    const pushCard = (lessonDate: string) => {
      const window = lessonWindowFromParts(lessonDate, lessonStart, lessonEnd);
      if (!window) return;
      const isOpen = now >= window.openAt && now <= window.closeAt;
      const isClosed = now > window.closeAt;
      groupCards.push({
        group_id: groupId,
        group_name: String(group.name || `Group #${groupId}`),
        date: lessonDate,
        start: lessonStart,
        end: lessonEnd,
        label: `${group.name || `Group #${groupId}`} · ${lessonDate} ${lessonStart}`,
        is_open: isOpen,
        is_closed: isClosed,
        subject: String(group.subject || "").trim(),
        teacher_name: String(group.teacher_name || "").trim(),
        student_count: Number(group.student_count || group.students_count || 0),
      });
    };
    if (/^\d{4}-\d{2}-\d{2}$/.test(lessonDateRaw)) {
      pushCard(lessonDateRaw);
    } else {
      const code = lessonDateRaw.toUpperCase();
      const weekdays = code === "MWF" ? [1, 3, 5] : code === "TTS" ? [2, 4, 6] : [];
      for (let i = -7; i < 15 && weekdays.length; i += 1) {
        const day = new Date(now);
        day.setDate(now.getDate() + i);
        if (!weekdays.includes(day.getDay())) continue;
        const iso = day.toISOString().slice(0, 10);
        pushCard(iso);
      }
    }
    if (!groupCards.length) continue;
    groupCards.sort((a, b) => {
      const rankDiff = rankCard(a) - rankCard(b);
      if (rankDiff) return rankDiff;
      const aStamp = new Date(`${a.date}T${a.start}:00`).getTime();
      const bStamp = new Date(`${b.date}T${b.start}:00`).getTime();
      if (rankCard(a) === 2) return bStamp - aStamp;
      return aStamp - bStamp;
    });
    cards.push(groupCards[0]);
  }
  cards.sort((a, b) => {
    const rankDiff = rankCard(a) - rankCard(b);
    if (rankDiff) return rankDiff;
    const aStamp = new Date(`${a.date}T${a.start}:00`).getTime();
    const bStamp = new Date(`${b.date}T${b.start}:00`).getTime();
    if (rankCard(a) === 2) return bStamp - aStamp;
    return aStamp - bStamp;
  });
  return cards.slice(0, take);
}

function addMinutesToTime(rawTime: string, minutes: number) {
  const [hRaw, mRaw] = String(rawTime || "00:00").split(":");
  const date = new Date();
  date.setHours(Number(hRaw || 0), Number(mRaw || 0), 0, 0);
  date.setMinutes(date.getMinutes() + Number(minutes || 0));
  return `${String(date.getHours()).padStart(2, "0")}:${String(date.getMinutes()).padStart(2, "0")}`;
}

function emitUiToast(message: string, tone: "info" | "success" | "error" = "info") {
  if (typeof window === "undefined") return;
  window.dispatchEvent(new CustomEvent("diamond:toast", { detail: { message, tone } }));
}

function canLoadAttendanceForLesson(card?: { date?: string; start?: string; end?: string } | null) {
  if (!card?.date || !card?.start) return { ok: false, message: "Dars vaqti topilmadi." };
  const window = lessonWindowFromParts(card.date, card.start, card.end);
  if (!window) return { ok: false, message: "Dars vaqti topilmadi." };
  const now = new Date();
  const windowMessage = "Davomatni faqat dars boshlanishidan 10 daqiqa oldin va dars tugagandan 24 soat ichida belgilash mumkin.";
  if (now < window.openAt) {
    return { ok: false, message: windowMessage };
  }
  if (now > window.closeAt) {
    return { ok: false, message: windowMessage };
  }
  return { ok: true, message: "" };
}

