function StudentPublicOfferScreen({ onAgreed }: { onAgreed: () => void }) {
  const tt = useWebT();
  const [readChecked, setReadChecked] = useState(false);
  const [agreeChecked, setAgreeChecked] = useState(false);
  const [loading, setLoading] = useState(false);

  return (
    <main className="placement-page process-runtime-page">
      <section className="placement-card placement-runtime-card">
        <article className="panel-card max-w-3xl mx-auto w-full p-6 sm:p-8 bg-surface dark:bg-navy-900 rounded-2xl shadow-xl">
          <h2 className="text-2xl font-black text-ink-900 dark:text-white mb-6 text-center">
            {tt("landing.footer.oferta", "Ommaviy Oferta")}
          </h2>
          
          <div className="mb-8 max-h-[50vh] overflow-y-auto bg-white dark:bg-white rounded-xl border border-line dark:border-white/10 flex justify-center custom-scrollbar">
            <img 
              src="/assets/ommaviy-oferta.png" 
              alt="Ommaviy Oferta" 
              className="max-w-full h-auto object-contain"
            />
          </div>

          <div className="space-y-4 bg-surface-soft dark:bg-navy-950 p-5 rounded-xl border border-line dark:border-white/10 mb-8">
            <label className="flex items-start gap-3 cursor-pointer group">
              <div className="relative flex items-center justify-center mt-0.5">
                <input 
                  type="checkbox" 
                  className="peer sr-only"
                  checked={readChecked}
                  onChange={(e) => setReadChecked(e.target.checked)}
                />
                <div className="w-5 h-5 rounded-md border-2 border-ink-300 dark:border-navy-600 peer-checked:bg-cyan-500 peer-checked:border-cyan-500 transition-all"></div>
                <svg className="absolute w-3.5 h-3.5 text-white pointer-events-none opacity-0 peer-checked:opacity-100 transition-opacity" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                </svg>
              </div>
              <span className="text-sm font-medium text-ink-700 dark:text-navy-200 group-hover:text-ink-900 dark:group-hover:text-white transition-colors">
                {tt("public_offer.read", "Ommaviy oferta shartlari bilan tanishdim")}
              </span>
            </label>

            <label className="flex items-start gap-3 cursor-pointer group">
              <div className="relative flex items-center justify-center mt-0.5">
                <input 
                  type="checkbox" 
                  className="peer sr-only"
                  checked={agreeChecked}
                  onChange={(e) => setAgreeChecked(e.target.checked)}
                />
                <div className="w-5 h-5 rounded-md border-2 border-ink-300 dark:border-navy-600 peer-checked:bg-cyan-500 peer-checked:border-cyan-500 transition-all"></div>
                <svg className="absolute w-3.5 h-3.5 text-white pointer-events-none opacity-0 peer-checked:opacity-100 transition-opacity" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                </svg>
              </div>
              <span className="text-sm font-medium text-ink-700 dark:text-navy-200 group-hover:text-ink-900 dark:group-hover:text-white transition-colors">
                {tt("public_offer.agree", "Ommaviy oferta shartlariga roziman")}
              </span>
            </label>
          </div>

          <div className="flex justify-center h-[52px]">
            {readChecked && agreeChecked ? (
              <button 
                className={`btn btn-primary w-full max-w-xs transition-all duration-300 animate-in fade-in zoom-in-95 ${loading ? "opacity-50 pointer-events-none" : ""}`}
                onClick={async () => {
                  setLoading(true);
                  try {
                    await onAgreed();
                  } finally {
                    setLoading(false);
                  }
                }}
                disabled={loading}
              >
                {loading ? tt("common.loading", "Yuklanmoqda...") : tt("common.continue", "Davom etish")}
              </button>
            ) : null}
          </div>
        </article>
      </section>
    </main>
  );
}

