  function updateGroupStudentCountLocal(groupId: number, groupCount: number | undefined) {
    if (!Number.isFinite(Number(groupCount))) return;
    const patchGroupRows = (rows: GenericRow[] | null): GenericRow[] | null => {
      const source = rows || groups || [];
      if (!source.length) return rows;
      return source.map((group) => (
        Number(group.id || 0) === Number(groupId)
          ? { ...group, student_count: Number(groupCount || 0), students_count: Number(groupCount || 0) }
          : group
      ));
    };
    setAdminGroupsFallback((prev) => patchGroupRows(prev));
    setPaymentsGroupsFallback((prev) => patchGroupRows(prev));
  }

