  async function savePaymentMethodDraft() {
    const cardNumber = String(paymentMethodDraft.card_number || "").trim();
    const ownerFirstName = String(paymentMethodDraft.owner_first_name || "").trim();
    const ownerLastName = String(paymentMethodDraft.owner_last_name || "").trim();
    if (!cardNumber || !ownerFirstName || !ownerLastName) return;
    const token = localStorage.getItem("diamond_token");
    if (!token) return;
    setPaymentMethodsSaving(true);
    try {
      const url = paymentMethodDraft.id
        ? `${API_BASE}/admin/payments/methods/${paymentMethodDraft.id}`
        : `${API_BASE}/admin/payments/methods`;
      const method = paymentMethodDraft.id ? "PATCH" : "POST";
      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          card_number: cardNumber,
          owner_first_name: ownerFirstName,
          owner_last_name: ownerLastName,
          is_default: Boolean(paymentMethodDraft.is_default),
          active: Boolean(paymentMethodDraft.active),
        }),
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(String(payload?.detail || "Payment method saqlanmadi"));
      }
      setPaymentMethods((payload.items || []) as GenericRow[]);
      setPaymentMethodDraft({
        card_number: "",
        owner_first_name: "",
        owner_last_name: "",
        is_default: false,
        active: true,
      });
    } finally {
      setPaymentMethodsSaving(false);
    }
  }

  async function deactivatePaymentMethod(methodId: number) {
    const token = localStorage.getItem("diamond_token");
    if (!token || !methodId) return;
    setPaymentMethodsSaving(true);
    try {
      const response = await fetch(`${API_BASE}/admin/payments/methods/${methodId}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(String(payload?.detail || "Payment method o'chirilmadi"));
      setPaymentMethods((payload.items || []) as GenericRow[]);
      setPaymentsConfirmDraft((prev) => {
        if (Number(prev.cardId || 0) !== Number(methodId || 0)) return prev;
        return { ...prev, cardId: 0 };
      });
    } finally {
      setPaymentMethodsSaving(false);
    }
  }

