  async function loadPaymentsStats() {
    const token = localStorage.getItem("diamond_token");
    if (!token) {
      setPaymentsStats({});
      return;
    }
    paymentsStatsReqRef.current += 1;
    const requestId = paymentsStatsReqRef.current;
    if (paymentsStatsAbortRef.current) {
      paymentsStatsAbortRef.current.abort();
    }
    const controller = new AbortController();
    paymentsStatsAbortRef.current = controller;
    setPaymentsStatsLoading(true);
    setPaymentsGeneralError("");
    const params = new URLSearchParams();
    params.set("ym", paymentsMonthFilter);
    if (paymentsDateFrom) params.set("date_from", paymentsDateFrom);
    if (paymentsDateTo) params.set("date_to", paymentsDateTo);
    if (deferredPaymentsTeacherFilter.trim()) params.set("teacher_name", deferredPaymentsTeacherFilter.trim());
    if (paymentsSubjectFilter !== "all") params.set("subject", paymentsSubjectFilter);
    if (paymentsStatusFilter !== "all") params.set("payment_status", paymentsStatusFilter);
    if (paymentsMethodFilter !== "all") params.set("payment_method", paymentsMethodFilter);
    const canUseFastDashboard =
      !paymentsDateFrom &&
      !paymentsDateTo &&
      !paymentsDayFilter &&
      paymentsLessonDayFilter === "all" &&
      !deferredPaymentsTeacherFilter.trim() &&
      !deferredPaymentsGroupQuery.trim() &&
      paymentsSubjectFilter === "all" &&
      paymentsStatusFilter === "all" &&
      paymentsMethodFilter === "all";
    try {
      if (canUseFastDashboard) {
        const dashboardParams = new URLSearchParams();
        dashboardParams.set("ym", paymentsMonthFilter);
        if (paymentsStatusFilter !== "all") dashboardParams.set("status", paymentsStatusFilter);
        const dashboard = await requestJson<GenericRow>(`/admin/payments/dashboard?${dashboardParams.toString()}`, {
          token,
          signal: controller.signal,
          timeoutMs: 30000,
          retries: 0,
        });
        if (controller.signal.aborted || requestId !== paymentsStatsReqRef.current) return;
        const stats = (dashboard.stats || {}) as GenericRow;
        const items = ((dashboard.items || []) as GenericRow[]);
        const totalPaid = Number(stats.total_paid_amount || 0);
        const totalDebt = Number(stats.total_debt_amount || 0);
        const totalDiscount = Number(stats.discount_total || 0);
        const totalRefund = Number(stats.refund_total || stats.total_refund_amount || 0);
        const totalOverpay = Number(stats.overpayment_total || 0);
        const totalExpected = Number(stats.total_expected_amount || (totalPaid + totalDebt));
        const totalFinal = Number(stats.total_final_payable_amount || totalExpected);
        const comparisonFrom = (key: "group_name" | "teacher_name") => {
          const bucket = new Map<string, GenericRow & { studentsSet?: Set<number>; groupIds?: Set<number>; statusLists?: Record<string, number[]> }>();
          for (const row of items) {
            const name = String(row[key] || (key === "group_name" ? row.group_id : "-") || "-");
            const current = bucket.get(name) || {
              group_id: key === "group_name" ? Number(row.group_id || 0) : undefined,
              group_name: key === "group_name" ? name : undefined,
              teacher_id: key === "teacher_name" ? Number(row.teacher_id || 0) : undefined,
              teacher_name: key === "group_name" ? String(row.teacher_name || "-") : name,
              paid_amount: 0,
              debt_amount: 0,
              expected_amount: 0,
              final_amount: 0,
              discount_amount: 0,
              refund_amount: 0,
              student_count: 0,
              studentsSet: new Set<number>(),
              groupIds: new Set<number>(),
              statusLists: { paid: [], unpaid: [], partial: [], overdue: [], overpayment: [] },
            };
            current.paid_amount = Number(current.paid_amount || 0) + Number(row.paid_amount || 0);
            current.debt_amount = Number(current.debt_amount || 0) + Number(row.debt_amount || 0);
            current.expected_amount = Number(current.expected_amount || 0) + Number(row.original_amount || row.final_amount || 0);
            current.final_amount = Number(current.final_amount || 0) + Number(row.final_amount || 0);
            current.discount_amount = Number(current.discount_amount || 0) + Number(row.discount_amount || 0);
            current.refund_amount = Number(current.refund_amount || 0) + Number(row.refund_amount || 0);
            const gid = Number(row.group_id || 0);
            if (gid > 0) current.groupIds?.add(gid);
            const uid = Number(row.user_id || 0);
            if (uid > 0) {
              current.studentsSet?.add(uid);
              const status = String(row.status || "").toLowerCase();
              const lists = current.statusLists || {};
              if (status.includes("ortiqcha")) lists.overpayment?.push(uid);
              else if (status.includes("kechik")) lists.overdue?.push(uid);
              else if (status.includes("qisman")) lists.partial?.push(uid);
              else if (status.includes("to'langan")) lists.paid?.push(uid);
              else lists.unpaid?.push(uid);
            }
            bucket.set(name, current);
          }
          return Array.from(bucket.values()).map((row): GenericRow => {
            const lists = row.statusLists || {};
            const finalAmount = Number(row.final_amount || 0);
            const paidAmount = Number(row.paid_amount || 0);
            return {
              ...row,
              student_count: row.studentsSet?.size || 0,
              group_count: row.groupIds?.size || 0,
              completion_percent: finalAmount > 0 ? (paidAmount / finalAmount) * 100 : 0,
              status_lists: lists,
              paid_students: lists.paid || [],
              unpaid_students: lists.unpaid || [],
              partial_students: lists.partial || [],
              overdue_students: lists.overdue || [],
              overpayment_students: lists.overpayment || [],
              studentsSet: undefined,
              groupIds: undefined,
              statusLists: undefined,
            };
          }).sort((a: GenericRow, b: GenericRow) => Number(b.expected_amount || 0) - Number(a.expected_amount || 0));
        };
        const dashboardGroupComparison = ((dashboard.group_comparison || []) as GenericRow[]);
        const dashboardTeacherComparison = ((dashboard.teacher_comparison || []) as GenericRow[]);
        setPaymentsStats({
          ym: dashboard.ym || paymentsMonthFilter,
          summary: {
            student_count: Number(stats.student_count || 0),
            total_paid_amount: totalPaid,
            total_debt_amount: totalDebt,
            total_expected_amount: totalExpected,
            total_final_payable_amount: totalFinal,
            total_discount_amount: totalDiscount,
            total_refund_amount: totalRefund,
            total_overpayment_amount: totalOverpay,
          },
          status_counts: {
            paid: Number(stats.paid_students || 0),
            unpaid: Number(stats.unpaid_students || 0),
            partial: Number(stats.partial_students || 0),
            overdue: Number(stats.late_students || 0),
            overpayment: Number(stats.overpayment_students || 0),
          },
          chart_data: {
            series: [{
              month: dashboard.ym || paymentsMonthFilter,
              paid_amount: totalPaid,
              debt_amount: totalDebt,
              expected_amount: totalExpected,
              final_amount: totalFinal,
            }],
            pie: { paid: totalPaid, debt: totalDebt, overpayment: totalOverpay, paid_amount: totalPaid, debt_amount: totalDebt, overpayment_amount: totalOverpay },
          },
          group_comparison: dashboardGroupComparison.length ? dashboardGroupComparison : comparisonFrom("group_name"),
          teacher_comparison: dashboardTeacherComparison.length ? dashboardTeacherComparison : comparisonFrom("teacher_name"),
          jobs: dashboard.jobs || [],
          fast_path: true,
        });
        setPaymentsGeneralError("");
        return;
      }
      const payload = await requestJson<GenericRow>(`/admin/payments/stats?${params.toString()}`, {
        token,
        signal: controller.signal,
        timeoutMs: 45000,
        retries: 1,
      });
      if (controller.signal.aborted || requestId !== paymentsStatsReqRef.current) return;
      setPaymentsStats(payload || {});
      setPaymentsGeneralError("");
    } catch (error) {
      if (controller.signal.aborted || requestId !== paymentsStatsReqRef.current) return;
      const normalized = normalizeNetworkError(error);
      setPaymentsGeneralError(String(normalized.message || "Payments statistics could not be loaded"));
    } finally {
      if (requestId === paymentsStatsReqRef.current) setPaymentsStatsLoading(false);
    }
  }

  function _derivePaymentConfirmDraft(detailPayload: GenericRow | null, monthKey: string, preferredGroupId?: number) {
    const months = ((detailPayload?.overview?.months || []) as GenericRow[]);
    const monthItem =
      months.find((row) => String(row.ym || "") === String(monthKey || "")) ||
      ((detailPayload?.overview?.current_month || null) as GenericRow | null);
    const monthRows = ((monthItem?.items || []) as GenericRow[]);
    const chosenGroupId =
      Number(preferredGroupId || 0) > 0
        ? Number(preferredGroupId || 0)
        : Number(monthRows[0]?.group_id || 0);
    const chosen = monthRows.find((row) => Number(row.group_id || 0) === chosenGroupId) || monthRows[0] || null;
    const debtAmount = Number(chosen?.debt_amount || 0);
    setPaymentsConfirmDraft((prev) => ({
      ...prev,
      ym: String(monthKey || prev.ym || new Date().toISOString().slice(0, 7)),
      groupId: Number(chosenGroupId || 0),
      amount: debtAmount > 0 ? debtAmount.toFixed(2) : "",
    }));
  }

  function getRefundablePaymentTransaction() {
    const selectedUserId = Number(paymentsSelectedStudentId || 0);
    const selectedGroup = Number(paymentsConfirmDraft.groupId || paymentsSelectedGroupId || 0);
    const selectedYm = String(paymentsConfirmDraft.ym || paymentsMonthFilter || "").trim();
    return (paymentsTxRows || []).find((row) => {
      const transactionId = Number(row.id || 0);
      if (transactionId <= 0 || String(row.record_type || "payment") === "refund") return false;
      if (Number(row.user_id || 0) !== selectedUserId) return false;
      if (selectedGroup > 0 && Number(row.group_id || 0) !== selectedGroup) return false;
      if (selectedYm && String(row.ym || "") !== selectedYm) return false;
      const paidAmount = Number(row.payment_dcoin_amount || row.paid_amount || 0);
      const refundedAmount = Number(row.refunded_amount || 0);
      return paidAmount - refundedAmount > 1e-9;
    }) || null;
  }

  async function openPaymentCalculation(studentIdArg?: number) {
    const token = localStorage.getItem("diamond_token");
    const selectedStudentId = Number(studentIdArg || paymentsSelectedStudentId || 0);
    if (!token || !selectedStudentId) return;
    setPaymentsCalcLoading(true);
    setPaymentsSelectedStudentId(selectedStudentId);
    try {
      const [calcPayload, detailPayload] = await Promise.all([
        requestJson<GenericRow>(
          `/admin/payments/preview?user_id=${selectedStudentId}&ym=${encodeURIComponent(paymentsMonthFilter)}${
            paymentsSelectedGroupId > 0 ? `&group_id=${paymentsSelectedGroupId}` : ""
          }`,
          { token },
        ),
        requestJson<GenericRow>(
          `/admin/payments/students/${selectedStudentId}/detail?ym=${encodeURIComponent(paymentsMonthFilter)}&include_history=false`,
          { token },
        ),
      ]);
      setPaymentsCalcModal(calcPayload || null);
      setPaymentsDetail(detailPayload || null);
      _derivePaymentConfirmDraft(detailPayload || null, paymentsMonthFilter, paymentsSelectedGroupId > 0 ? paymentsSelectedGroupId : undefined);
      setPaymentsCalcPopupOpen(true);
    } finally {
      setPaymentsCalcLoading(false);
    }
  }

  async function confirmStudentPayment(mode: "full" | "partial", amountOverride?: number) {
    const userId = Number(paymentsSelectedStudentId || 0);
    const groupId = Number(paymentsConfirmDraft.groupId || 0);
    const monthKey = String(paymentsConfirmDraft.ym || "").trim();
    if (!userId || !groupId || !monthKey) return;
    const fullAmountSource = amountOverride ?? paymentsConfirmDraft.amount;
    const amountNumber = mode === "full"
      ? Number(fullAmountSource || 0)
      : Number(String(paymentsConfirmDraft.amount || "").replace(",", "."));
    if (!Number.isFinite(amountNumber) || amountNumber <= 0) return;
    setPaymentsConfirmBusy(true);
    try {
      const result = await onAdminCall(
        `/admin/payments/students/${userId}/confirm`,
        {
          ym: monthKey,
          group_id: groupId,
          amount: Number(amountNumber.toFixed(2)),
          payment_method: paymentsConfirmDraft.paymentMethod,
          card_id: paymentsConfirmDraft.paymentMethod === "card" && Number(paymentsConfirmDraft.cardId || 0) > 0 ? Number(paymentsConfirmDraft.cardId) : null,
          note: String(paymentsConfirmDraft.note || "").trim() || null,
          is_advance: Boolean(paymentsConfirmDraft.isAdvance),
        },
        "POST",
        "Payment confirmed",
      );
      if (!result) return;
      const returnedDebt = Number(result.debt_amount || 0);
      setPaymentsConfirmDraft((prev) => ({
        ...prev,
        amount: returnedDebt > 0 ? returnedDebt.toFixed(2) : "",
        note: "",
      }));
      void Promise.allSettled([
        loadPaymentsTransactions(paymentsSelectedGroupId > 0 ? paymentsSelectedGroupId : undefined),
        loadPaymentsStats(),
        openPaymentCalculation(userId),
        paymentsSelectedGroupId > 0 ? loadPaymentsGroupStudents(paymentsSelectedGroupId) : Promise.resolve([]),
      ]);
    } finally {
      setPaymentsConfirmBusy(false);
    }
  }

  async function refundSelectedPayment() {
    const transaction = getRefundablePaymentTransaction();
    if (!transaction) {
      emitUiToast("Refund uchun tranzaksiya topilmadi.", "error");
      return;
    }
    const transactionId = Number(transaction.id || 0);
    const refundableAmount = Math.max(0, Number(transaction.payment_dcoin_amount || transaction.paid_amount || 0) - Number(transaction.refunded_amount || 0));
    const draftAmount = Number(String(paymentsConfirmDraft.amount || "").replace(",", "."));
    const amount = Number.isFinite(draftAmount) && draftAmount > 0 ? Math.min(draftAmount, refundableAmount) : refundableAmount;
    const note = String(paymentsConfirmDraft.note || "").trim();
    if (!note) {
      emitUiToast("Refund uchun izoh majburiy.", "error");
      return;
    }
    if (!transactionId || amount <= 0) return;
    setPaymentsRefundBusy(true);
    try {
      const result = await onAdminCall(
        `/admin/payments/transactions/${transactionId}/refund`,
        { amount: Number(amount.toFixed(2)), note },
        "POST",
        "Refund completed",
      );
      if (!result) return;
      setPaymentsConfirmDraft((prev) => ({ ...prev, amount: "", note: "" }));
      await Promise.allSettled([
        loadPaymentsTransactions(paymentsSelectedGroupId > 0 ? paymentsSelectedGroupId : undefined),
        loadPaymentsStats(),
        paymentsSelectedGroupId > 0 ? loadPaymentsGroupStudents(paymentsSelectedGroupId) : Promise.resolve([]),
        openPaymentCalculation(Number(paymentsSelectedStudentId || 0)),
      ]);
    } finally {
      setPaymentsRefundBusy(false);
    }
  }

  async function downloadPaymentExport(mode: "default" | "filtered" | "month" | "custom" = "default") {
    const token = localStorage.getItem("diamond_token");
    if (!token) return;
    setPaymentsExportBusy(true);
    try {
      const payload: GenericRow = { months: 6 };
      if (mode !== "default") {
        if (paymentsSelectedGroupId > 0) payload.group_id = Number(paymentsSelectedGroupId);
        if (paymentsTeacherFilter.trim()) payload.teacher_name = paymentsTeacherFilter.trim();
        if (paymentsSubjectFilter !== "all") payload.subject = paymentsSubjectFilter;
        if (paymentsStatusFilter !== "all") payload.payment_status = paymentsStatusFilter;
        if (paymentsMethodFilter !== "all") payload.payment_method = paymentsMethodFilter;
      }
      if (mode === "month") {
        const month = String(paymentsExportMonth || "").trim();
        if (!/^\d{4}-\d{2}$/.test(month)) {
          throw new Error("Oy formati noto'g'ri");
        }
        const [yearRaw, monthRaw] = month.split("-");
        const year = Number(yearRaw);
        const monthIndex = Number(monthRaw);
        const start = `${yearRaw}-${monthRaw}-01`;
        const endDate = new Date(year, monthIndex, 0);
        const end = `${yearRaw}-${monthRaw}-${String(endDate.getDate()).padStart(2, "0")}`;
        payload.months = 1;
        payload.date_from = start;
        payload.date_to = end;
      }
      if (mode === "custom") {
        payload.date_from = paymentsExportDateFrom || null;
        payload.date_to = paymentsExportDateTo || null;
      }
      const response = await fetch(`${API_BASE}/admin/payments/export`, {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify(payload),
      });
      if (!response.ok) {
        const errorPayload = await response.json().catch(() => ({}));
        throw new Error(String(errorPayload?.detail || "Could not export payment history"));
      }
      const blob = await response.blob();
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download =
        mode === "custom"
          ? "payment_history_custom.xlsx"
          : mode === "month"
            ? "payment_history_selected_month.xlsx"
            : mode === "filtered"
              ? "payment_history_filtered.xlsx"
              : "payment_history_last_6_months.xlsx";
      document.body.appendChild(anchor);
      anchor.click();
      anchor.remove();
      URL.revokeObjectURL(url);
    } catch (error) {
      const normalized = normalizeNetworkError(error);
      setPaymentsGeneralError(String(normalized.message || "Could not export payment history"));
    } finally {
      setPaymentsExportBusy(false);
    }
  }

