    const token = localStorage.getItem("diamond_token");
    if (!token) return;
    const controller = new AbortController();
    const limit = 50;
    const params = new URLSearchParams();
    params.set("limit", String(limit));
    params.set("offset", String(Math.max(0, (dpointHistoryPage - 1) * limit)));
    if (debouncedDpointHistorySearch.trim()) params.set("q", debouncedDpointHistorySearch.trim());
