  async function markAdminAttendanceStatus(userId: number, status: string, dateArg?: string) {
    if (!activeAdminAttendanceCard) return;
    const day = String(dateArg || activeAdminAttendanceCard.date || attendanceDate || "");
    const dayInfo = attendanceDates.find((item) => String(item.date) === day);
    if (dayInfo && !dayInfo.open) {
      emitUiToast("Davomatni faqat dars boshlanishidan 10 daqiqa oldin va dars tugagandan 24 soat ichida belgilash mumkin.", "error");
      return;
    }
    const cellKey = `${userId}:${day}`;
    if (attendanceCellAllowed[cellKey] === false) {
      emitUiToast("Davomatni faqat dars boshlanishidan 10 daqiqa oldin va dars tugagandan 24 soat ichida belgilash mumkin.", "error");
      return;
    }
    const previousStatus = String(attendanceMap[cellKey] || "");
    setAdminStatusDraft((prev) => ({ ...prev, [userId]: status }));
    setAttendanceMap((prev) => ({ ...prev, [cellKey]: status }));
    setAttendanceFinalizeNote("");
    const result = await onAdminCall(
      "/admin/attendance/mark",
      {
        group_id: Number(activeAdminAttendanceCard.group_id || 0),
        user_id: userId,
        date: day,
        status,
      },
      "POST",
      `Marked ${String(status || "").toLowerCase()}`,
    );
    if (!result) {
      setAttendanceMap((prev) => ({ ...prev, [cellKey]: previousStatus }));
      setAdminStatusDraft((prev) => ({ ...prev, [userId]: previousStatus }));
      emitUiToast("Davomat saqlanmadi. Qayta urinib ko'ring.", "error");
    }
  }

  async function finishAdminAttendance() {
    if (!activeAdminAttendanceCard || !attendanceRows.length || attendanceFinalizeBusy) return;
    const token = localStorage.getItem("diamond_token");
    if (!token) return;
    setAttendanceFinalizeBusy(true);
    setAttendanceFinalizeNote("");
    try {
      await Promise.all(
        attendanceRows.map((row) => {
          const userId = Number(row.user_id || 0);
          const statusRaw = String(adminStatusDraft[userId] || row.status || "").trim();
          if (!ATTENDANCE_STATUSES.includes(statusRaw as (typeof ATTENDANCE_STATUSES)[number])) {
            return Promise.resolve(null);
          }
          const status = statusRaw;
          return requestJson(
            "/admin/attendance/mark",
            {
              method: "POST",
              token,
              body: {
                group_id: Number(activeAdminAttendanceCard.group_id || 0),
                user_id: userId,
                date: String(activeAdminAttendanceCard.date || attendanceDate),
                status,
              },
            },
          );
        }),
      );
      await loadAttendance(activeAdminAttendanceCard);
      setAttendanceFinalizeNote(tt("admin.attendance.finalized", "Davomat yakunlandi"));
    } catch (err) {
      setAttendanceFinalizeNote(err instanceof Error ? err.message : tt("common.error", "Xatolik yuz berdi"));
    } finally {
      setAttendanceFinalizeBusy(false);
    }
  }

  async function triggerPasswordReset(targetUser: GenericRow) {
    const uid = Number(targetUser.id || 0);
    if (!uid || resetPasswordPending[uid]) return;
    setResetPasswordPending((prev) => ({ ...prev, [uid]: true }));
    try {
      const result = await onAdminCall(`/admin/users/${uid}/reset-password`, {}, "POST", "Password reset");
      if (result?.password) {
        setResetPasswordInfo({
          userName: String(targetUser.full_name || "-"),
          loginId: String(targetUser.login_id || "-"),
          password: String(result.password || ""),
          qr_token: typeof result?.qr_token === "string" ? result.qr_token : null,
          qr_payload: typeof result?.qr_payload === "string" ? result.qr_payload : null,
          qr_expires_at: typeof result?.qr_expires_at === "string" ? result.qr_expires_at : null,
        });
      }
      if (selectedUserId && Number(selectedUserId) === uid) {
        loadUserDetail(uid);
      }
    } finally {
      setResetPasswordPending((prev) => ({ ...prev, [uid]: false }));
    }
  }

  async function toggleUserBlocked(targetUser: GenericRow) {
    const uid = Number(targetUser.id || 0);
    if (!uid) return;
    const nextBlocked = !Boolean(targetUser.blocked);
    const result = await onAdminCall(
      `/admin/users/${uid}`,
      { blocked: nextBlocked, access_enabled: !nextBlocked },
      "PATCH",
      nextBlocked ? "User blocked" : "User unblocked",
    );
    const refreshed = (result?.user || {}) as GenericRow;
    setAdminUsersFallback((prev) =>
      prev
        ? prev.map((row) =>
            Number(row.id || 0) === uid
              ? { ...row, ...refreshed, blocked: nextBlocked, access_enabled: !nextBlocked }
              : row,
          )
        : prev,
    );
    if (Number(selectedUserId || 0) === uid) {
      loadUserDetail(uid);
    }
  }

